"""Language-specific lectures: concepts, runnable fragments and project briefs."""
# title | explanation | fragment | laboratory
SPECIAL = {
'python': [
('Объекты, ссылки и изменяемость','Имена Python ссылаются на объекты. Присваивание списка другому имени не создаёт независимую копию. Поверхностная копия создаёт новый внешний список, но вложенные объекты остаются общими. is проверяет идентичность, == сравнивает значения. Изменяемые значения по умолчанию функции создаются один раз при определении функции, поэтому список аргумента лучше создавать внутри при значении None.', 'a = [[1], [2]]\nb = a.copy()\nb[0].append(3)\nprint(a)  # [[1, 3], [2]]', 'Сделай независимую копию двумерной сетки. Напиши функцию добавления заметки без общего списка между вызовами.'),
('Срезы и comprehensions','Срез задаёт полуоткрытый диапазон start:stop:step. Отрицательные индексы отсчитываются от конца, но выход за границу обычного индекса вызывает IndexError. Списковое включение удобно для короткого преобразования или фильтра. Для сложной логики обычный цикл читается лучше. Срез списка создаёт новый список; это требует памяти пропорционально размеру результата.', 'numbers = [1, 2, 3, 4, 5]\nsquares = [x * x for x in numbers if x % 2 == 0]\nprint(numbers[1:4], squares)', 'Сделай обработку списка оценок без изменения исходного списка. Сравни срез, копию и ссылку.'),
('Распаковка, args и kwargs','Распаковка связывает элементы и имена по структуре. Звёздочка собирает остаток последовательности или раскрывает аргументы вызова. Позиционные и именованные параметры являются частью интерфейса функции; не меняй их порядок без причины. args — кортеж позиционных аргументов, kwargs — словарь именованных. Явные параметры обычно понятнее универсального интерфейса без контракта.', 'def report(title, *values, unit="шт"):\n    return f"{title}: {sum(values)} {unit}"\nprint(report("Заказ", 2, 3, unit="книг"))', 'Напиши функцию отчёта с обязательным заголовком и необязательными настройками. Проверь ошибочные имена параметров.'),
('Итераторы и генераторы','Итерируемый объект предоставляет итератор, а итератор выдаёт очередной элемент или завершает обход. Генератор с yield сохраняет своё состояние между запросами и обрабатывает данные лениво. Он обычно одноразовый: повторный обход исчерпанного генератора не повторяет вычисление. Это удобно для больших файлов, но открытый ресурс должен жить достаточно долго.', 'def squares(limit):\n    for n in range(limit):\n        yield n * n\nprint(list(squares(5)))', 'Сделай генератор строк журнала, удовлетворяющих фильтру, без чтения всего файла в память.'),
('Контекстные менеджеры и with','with гарантирует вызов логики завершения контекста, в том числе при исключении. Для файла это обычно означает закрытие дескриптора. Контекстный менеджер не делает операцию автоматически атомарной и не подавляет все ошибки. contextlib.contextmanager позволяет написать простой собственный контекст через try/finally.', 'from pathlib import Path\nwith Path("notes.txt").open("w", encoding="utf-8") as handle:\n    handle.write("Первая заметка\\n")', 'Реализуй надёжное сохранение заметок во временный файл с заменой основного через pathlib.'),
('Исключения Python и собственные ошибки','except должен ловить ожидаемый тип, например ValueError при неверном числе. else выполняется при успешном завершении try, finally — независимо от результата. Для предметной ошибки можно объявить свой подкласс Exception. Конструкция raise ... from ... сохраняет цепочку исходной причины. Не перехватывай BaseException для обычного восстановления: он включает сигналы завершения.', 'def parse_age(text):\n    age = int(text)\n    if not 0 <= age <= 150:\n        raise ValueError("Возраст вне диапазона")\n    return age', 'Раздели ошибки формата и диапазона в консольной анкете. Покажи понятные сообщения и сохрани причину для диагностики.'),
('Классы, dataclass и композиция','Класс задаёт поведение и состояние экземпляра. self — явный параметр методов экземпляра. dataclass генерирует стандартные методы для записей, но не заменяет проверку инвариантов. Для изменяемого поля используй default_factory. Композиция выражает отношение «содержит» и часто проще наследования. У frozen-записи нельзя обычным присваиванием менять поля, но вложенный список всё ещё может быть изменяемым.', 'from dataclasses import dataclass, field\n@dataclass\nclass Notebook:\n    title: str\n    notes: list[str] = field(default_factory=list)', 'Создай модель библиотеки через dataclass и сервис выдачи. Проверь, что два экземпляра не разделяют один список.'),
('Аннотации типов и Optional','Аннотации документируют ожидаемые типы и помогают статическому анализу, но интерпретатор обычно не проверяет их автоматически. str | None означает, что результата может не быть. Перед использованием нужно сузить вариант проверкой. Типы коллекций описывают элементы, а протоколы — доступное поведение. Не подменяй валидацию внешнего JSON одной аннотацией.', 'def find_name(names: list[str], prefix: str) -> str | None:\n    return next((name for name in names if name.startswith(prefix)), None)', 'Добавь типы к блокноту, обработай отсутствие найденной заметки и объясни границу между аннотацией и проверкой.'),
('Пакеты, venv и точка входа','Виртуальное окружение изолирует установленные пакеты проекта. python -m запускает модуль выбранным интерпретатором; pip лучше вызывать через тот же python -m pip. Импорт выполняет верхний уровень модуля, поэтому запуск приложения помещают под условие __name__ == "__main__". Не называй свой файл json.py или random.py рядом с кодом, который импортирует эти стандартные модули.', 'def main():\n    print("DevCat")\nif __name__ == "__main__":\n    main()', 'Раздели проект на пакет и точку входа. Создай venv, зафиксируй зависимости и опиши запуск без IDE.'),
('Стандартная библиотека: pathlib и datetime','pathlib представляет путь объектом и соединяет части оператором /. datetime различает наивные даты без часового пояса и осведомлённые значения. Для обмена событиями удобно сохранять UTC и показывать локальное время отдельно. Работа с календарём не сводится к прибавлению фиксированных секунд: переходы времени и длина месяцев требуют явной политики.', 'from pathlib import Path\nfrom datetime import datetime, timezone\nprint(Path("data") / "notes.json")\nprint(datetime.now(timezone.utc).isoformat())', 'Добавь дату создания заметки в UTC и вывод в локальном часовом поясе. Проверь сохранение после перезапуска.'),
('unittest и подмена зависимостей','unittest входит в стандартную библиотеку. TestCase группирует независимые сценарии, assertEqual сравнивает ожидаемое и фактическое значение. Внешний ввод лучше передать зависимости как параметр, чем заставлять тест читать реальную консоль. Временный каталог отделяет тестовые файлы от пользовательских. Подмена полезна на границе, а не для копирования внутреннего алгоритма.', 'import unittest\nclass SumTests(unittest.TestCase):\n    def test_empty(self):\n        self.assertEqual(sum([]), 0)', 'Напиши тесты ядра блокнота без реальной консоли. Добавь временное файловое хранилище и тест повреждённого JSON.'),
('asyncio: задачи, ожидание и отмена','async def создаёт корутинную функцию. Вызов возвращает корутину, которую нужно ожидать или запланировать. await отдаёт управление циклу событий на операции ожидания; обычный тяжёлый цикл процессора от этого не становится параллельным. Задачи требуют обработки отмены и завершения. Блокирующий ввод внутри цикла событий мешает всем другим задачам.', 'import asyncio\nasync def main():\n    await asyncio.sleep(0.01)\n    print("готово")\nasyncio.run(main())', 'Сделай асинхронный таймер с отменой и корректным завершением. Не используй сеть: воспроизведи ожидание через sleep.'),
('SQLite из Python и параметры запроса','sqlite3 позволяет хранить данные локально без отдельного сервера. Значения передаются параметрами запроса, а не конкатенацией SQL. Контекст соединения помогает завершать транзакции, но закрытие соединения требуется организовать отдельно. Явная схема и ограничения лучше, чем набор разрозненных JSON-файлов при сложных связях.', 'import sqlite3\nconnection = sqlite3.connect(":memory:")\nconnection.execute("CREATE TABLE notes(id INTEGER PRIMARY KEY, text TEXT)")\nconnection.execute("INSERT INTO notes(text) VALUES (?)", ("Привет",))\nprint(connection.execute("SELECT text FROM notes").fetchall())\nconnection.close()', 'Перенеси хранилище заметок в SQLite, сохрани параметризацию и протестируй откат транзакции.'),
('Проект: анализатор текстового журнала','Задача анализатора объединяет файловый ввод, разбор строк, словари и сортировку. Определи формат строки, например дата, уровень и сообщение. Парсер должен возвращать структурированное событие или объяснимую ошибку. Статистика отделяется от чтения файлов. Некорректные строки не должны молча превращаться в корректные события.', '# Этапы проекта:\n# parse_line -> Event | ошибка\n# summarize -> частоты уровней\n# format_report -> строка', 'Сделай CLI с выбором файла, фильтром уровня и отчётом. Добавь пустой файл, неверную строку, Unicode и большой поток.'),
('Проект: менеджер личной библиотеки','Проект библиотеки требует устойчивых идентификаторов, поиска, выдачи и возврата. Храни состояние отдельно от командного интерфейса. Сформулируй инварианты: книга не может быть выдана двум людям одновременно, возврат невыданной книги сообщает ошибку. Сохраняй только после успешной операции и проверь миграцию схемы.', '# Модули: model.py, service.py, storage.py, main.py\n# Операции: add, search, lend, return_book', 'Создай приложение из четырёх модулей, добавь JSON или SQLite, тесты и инструкцию запуска на чистом окружении.'),
('Выпуск проекта и самостоятельное чтение документации','Законченная программа включает не только код: нужны воспроизводимый запуск, примеры ввода, тесты и понятные ограничения. Читай документацию по конкретному вопросу: сигнатура, возвращаемое значение, исключения и пример. Отделяй стандартную библиотеку от стороннего пакета. Перед выпуском пройди сценарий нового пользователя в новом каталоге и проверь, что приложение не зависит от случайных файлов разработчика.', '# Чек-лист выпуска:\n# README, тесты, схема данных, версия, резервная копия', 'Выпусти свой блокнот: восстанови его из экспорта на другом каталоге данных, проведи демонстрацию без подсказок и запиши известные ограничения.'),
],
'cpp': [
('Ссылки, указатели и const','Ссылка задаёт другое имя уже существующего объекта, указатель хранит адрес и может быть пустым. const ограничивает изменение через конкретный путь доступа. Ссылка как параметр позволяет избежать копии; const T& подходит для чтения большого объекта. Указатель нельзя разыменовывать без проверки корректности адреса и времени жизни. Арифметика указателей допустима только в пределах соответствующего массива.', 'int value = 7;\nint& alias = value;\nconst int* pointer = &value;\nalias += 1;\nstd::cout << *pointer;', 'Напиши функцию перестановки двух целых по ссылкам и функцию чтения строки по const-ссылке. Нарисуй объекты и адресные связи.'),
('Время жизни и неопределённое поведение','Выход за границу, чтение неинициализированного значения и обращение к уничтоженному объекту могут вызвать неопределённое поведение. Это не обязано приводить к немедленному падению; оптимизатор может исходить из того, что такого пути нет. Время жизни локального объекта обычно заканчивается при выходе из блока. Возврат ссылки на локальную переменную создаёт висячую ссылку.', 'std::string make_name() {\n    std::string name = "DevCat";\n    return name;  // Возвращается значение\n}', 'Найди ошибки времени жизни в трёх небольших функциях. Собери исправленную версию с предупреждениями и санитайзерами вне приложения.'),
('RAII и управление ресурсами','RAII связывает ресурс со временем жизни объекта. Конструктор получает ресурс, деструктор освобождает, в том числе при исключении. std::vector, std::string и файловые потоки уже реализуют это правило. Ручные new/delete редко нужны в прикладном коде. Объект-владелец не должен случайно копировать уникальное владение, иначе ресурс будет освобождён дважды.', '{\n    std::ofstream file("notes.txt");\n    if (!file) throw std::runtime_error("Не открыть файл");\n    file << "DevCat\\n";\n} // Поток закрывается', 'Спроектируй владельца временного файла и объясни поведение при исключении между открытием и записью.'),
('vector, string и инвалидирование','std::vector хранит элементы непрерывно и умеет расти. Рост с перераспределением памяти может инвалидировать указатели, ссылки и итераторы. reserve задаёт вместимость, resize меняет число существующих элементов. operator[] не проверяет границу, at выбрасывает исключение при неверной позиции. std::string тоже имеет длину и вместимость, а его байты не всегда равны символам Unicode.', 'std::vector<int> values{3, 1, 4};\nvalues.reserve(20);\nvalues.push_back(2);\nstd::cout << values.at(0);', 'Сделай динамическую таблицу оценок. Проверь отличие size и capacity и не сохраняй ссылку через потенциальный рост.'),
('Итераторы, алгоритмы и лямбды','Стандартные алгоритмы принимают диапазоны итераторов, часто полуоткрытые [begin,end). Лямбда описывает локальное действие, а список захвата управляет доступом к внешним данным. Захват по ссылке требует, чтобы окружение ещё существовало при вызове. Компаратор сортировки обязан задавать строгое слабое упорядочение: для равных элементов он не должен возвращать true в обе стороны.', 'std::vector<int> values{5, 1, 3};\nstd::sort(values.begin(), values.end());\nauto it = std::find_if(values.begin(), values.end(), [](int x) { return x > 2; });', 'Отсортируй товары по цене и имени, отфильтруй отсутствующие. Опиши правило сравнения для равных цен.'),
('Классы и инварианты','Класс объединяет данные и операции, а private помогает контролировать изменение состояния. Конструктор должен создавать корректный объект. const-метод обещает не менять наблюдаемое состояние обычных полей через this. Инициализацию членов выполняют в списке инициализации; порядок определяется объявлением полей. Публичный интерфейс лучше делать небольшим и осмысленным.', 'class Counter {\n    int value_ = 0;\npublic:\n    void increment() { ++value_; }\n    int value() const { return value_; }\n};', 'Реализуй счёт с неотрицательным балансом и операцией списания. Проверь сохранение инварианта при отказе.'),
('Копирование, перемещение и правило нуля','Копирование создаёт отдельное значение, перемещение позволяет передать ресурсы. std::move само по себе не перемещает: оно меняет категорию выражения, чтобы мог быть выбран move-конструктор или присваивание. После перемещения объект остаётся корректным, но его значение часто не определено контрактом точнее. Правило нуля предлагает опираться на стандартные владельцы ресурсов и не писать специальные методы без необходимости.', 'std::vector<int> source{1, 2, 3};\nstd::vector<int> copy = source;\nstd::vector<int> moved = std::move(source);', 'Проследи копирование и перемещение модели с vector. Объясни, какие гарантии остаются у source.'),
('unique_ptr и shared_ptr','unique_ptr выражает единственного владельца и передаётся перемещением. shared_ptr разделяет владение через счётчик, а weak_ptr позволяет наблюдать без продления жизни. Цикл shared_ptr может удерживать объекты навсегда; weak_ptr разрывает такой цикл. Умный указатель не делает доступ из нескольких потоков автоматически безопасным.', 'auto value = std::make_unique<int>(42);\nauto owner = std::move(value);\nstd::cout << *owner;', 'Спроектируй дерево с уникальным владением дочерними узлами. Выбери невладеющий способ ссылки на родителя.'),
('Шаблоны и ограничения C++20','Шаблон описывает семейство функций или типов для разных аргументов. Ошибка может проявиться только при инстанцировании. Concepts позволяют выразить требования к операциям и улучшить диагностику. Обобщение полезно, когда контракт действительно одинаков, а не только похожи две строки кода. Реализации шаблонов обычно доступны в заголовке в точке инстанцирования.', 'template <typename T>\nT twice(T value) { return value + value; }\nstd::cout << twice(4);', 'Напиши обобщённую функцию ограничения диапазоном и сформулируй требования к типу.'),
('optional, variant и явное отсутствие','std::optional<T> выражает наличие или отсутствие значения. Проверка должна предшествовать разыменованию. std::variant хранит один из перечисленных вариантов, а std::visit помогает обработать каждый. Это удобнее специальных значений вроде -1, если -1 может быть обычным результатом. Отсутствие не обязательно является исключительной ошибкой.', 'std::optional<int> find_positive(const std::vector<int>& values) {\n    for (int value : values) if (value > 0) return value;\n    return std::nullopt;\n}', 'Верни результат поиска без опасного индекса -1. Добавь структурированное представление нескольких команд через variant.'),
('Исключения и гарантии безопасности','Исключение передаёт управление ближайшему подходящему обработчику и запускает разрушение локальных объектов. Базовая гарантия сохраняет корректность объектов, сильная — отсутствие изменения при неуспехе. Деструкторы не должны выбрасывать исключения во время раскрутки стека. noexcept — контракт, нарушение которого завершает процесс; не добавляй его механически.', 'try {\n    std::vector<int> values{1};\n    std::cout << values.at(5);\n} catch (const std::out_of_range& error) {\n    std::cerr << error.what();\n}', 'Сделай атомарное обновление каталога товаров: сначала проверь новую версию, затем замени старую.'),
('Заголовки, единицы трансляции и сборка','Каждый .cpp компилируется отдельно, затем компоновщик связывает определения. Заголовок содержит объявления, guard или pragma once защищает повторное включение. Не размещай обычное определение глобальной функции в нескольких единицах трансляции без соответствующего правила inline. CMake описывает цели и зависимости, а не просто список команд для одного компьютера.', '// stats.h\n#pragma once\nint add(int a, int b);\n// stats.cpp\nint add(int a, int b) { return a + b; }', 'Раздели проект на main.cpp, stats.h и stats.cpp. Собери их вместе и объясни ошибку undefined reference.'),
('Потоки, mutex и отсутствие гонок','std::thread выполняет функцию параллельно. Совместная запись в обычный объект без синхронизации может быть гонкой данных и неопределённым поведением. mutex защищает инвариант, а lock_guard удерживает блокировку по RAII. Атомарный счётчик подходит для отдельных операций, но не заменяет защиту сложной связи полей. Сначала ищи способ избежать общего изменяемого состояния.', 'std::mutex mutex;\nint total = 0;\nauto increment = [&] {\n    std::lock_guard<std::mutex> lock(mutex);\n    ++total;\n};', 'Сравни небезопасный общий счётчик с защищённым. Опиши, какие данные должны находиться под одной блокировкой.'),
('Проект: каталог книг с поиском','Каталог объединяет классы, vector, алгоритмы, файлы и обработку ошибок. Идентификатор книги не должен зависеть от текущего индекса в vector: удаление меняет позиции. У каждой операции есть проверяемый контракт. Отдели загрузку и сохранение от функций поиска и изменения.', '// Файлы: Book.h, Catalog.h, Catalog.cpp, main.cpp\n// Команды: add, remove, search, save', 'Создай каталог с устойчивыми id, сортировкой и резервной копией. Добавь тесты пустого каталога, повторов и повреждённого файла.'),
('Проект: интерпретатор команд','Разбор команды — отдельный этап от выполнения. Сначала получи структурированный запрос, затем проверь аргументы и только после этого меняй состояние. Кавычки и пробелы требуют явной грамматики. Интерпретатор учебных команд не должен передавать текст системной оболочке.', '// parse -> Command\n// validate -> допустимые аргументы\n// execute -> изменение модели', 'Сделай команды для блокнота с quoted-строками, историей и понятными ошибками. Не используй system() для выполнения команд.'),
('Выпуск: предупреждения, санитайзеры и документация','Предупреждения компилятора обнаруживают подозрительные конструкции, AddressSanitizer помогает находить ошибки памяти, UndefinedBehaviorSanitizer — отдельные виды неопределённого поведения. Эти инструменты дополняют тесты, но не доказывают отсутствие дефектов. README должен описывать стандарт C++20, сборку, запуск и ограничения формата данных.', '// Внешняя проверка Clang/GCC:\n// -Wall -Wextra -Wpedantic\n// -fsanitize=address,undefined -g', 'Подготовь самостоятельный выпуск проекта с CMake, тестами и инструкцией. Проверь сборку в новом каталоге без IDE.'),
],
}
SPECIAL['c'] = [
('Модель памяти и адрес объекта','Память хранит байтовые представления объектов, а тип определяет, как обращаться к ним. Оператор & получает адрес, * разыменовывает указатель. Размер типа узнают через sizeof, а не по предположению об операционной системе. Адрес допустим только при корректном выравнивании и действующем времени жизни объекта. Случайное целое число не становится безопасным указателем после приведения типа.', 'int number = 7;\nint *pointer = &number;\n*pointer = 9;\nprintf("%d %zu\\n", number, sizeof number);', 'Нарисуй две целые переменные и указатель, затем реализуй обмен значений через указатели.'),
('Массив и указатель — разные понятия','Массив содержит фиксированное число элементов. В большинстве выражений имя массива преобразуется в указатель на первый элемент, но sizeof массива и sizeof указателя дают разный смысл. Параметр функции вида int values[] фактически является указателем: длину нужно передать отдельно. Нельзя обращаться за последний элемент; указатель на позицию сразу после конца можно сравнивать, но не разыменовывать.', 'int values[] = {2, 4, 6};\nsize_t count = sizeof values / sizeof values[0];\nfor (size_t i = 0; i < count; ++i) printf("%d\\n", values[i]);', 'Напиши sum(const int *values, size_t count), проверь пустой диапазон и объясни, где доступна реальная длина массива.'),
('Строки C и завершающий ноль','Строка C — последовательность char до первого нулевого байта. Буфер должен содержать место и для данных, и для завершителя. strlen считает длину до нуля, а sizeof локального массива — весь размер буфера. fgets ограничивает чтение, но может сохранить перевод строки или прочитать только часть длинной строки. Побайтовые операции не равны обработке Unicode-символов.', 'char name[64];\nif (fgets(name, sizeof name, stdin)) {\n    name[strcspn(name, "\\n")] = \'\\0\';\n    printf("%s\\n", name);\n}', 'Сделай безопасный ввод имени в ограниченный буфер. Отдельно обнаружь слишком длинную строку и конец потока.'),
('malloc, calloc и владение','malloc выделяет блок неинициализированной памяти и возвращает NULL при неуспехе. calloc обнуляет выделенную память. Владелец блока обязан освободить его через free ровно один раз и не использовать после освобождения. Размер выделения рассчитывают с проверкой переполнения. Приведение результата malloc в C не требуется, но объявление функции из stdlib.h обязательно.', 'size_t count = 10;\nint *values = calloc(count, sizeof *values);\nif (!values) return 1;\nvalues[0] = 42;\nfree(values);', 'Создай динамический массив оценок. Опиши владельца памяти, обработай отказ выделения и освободи все пути выхода.'),
('realloc и динамическая ёмкость','realloc может переместить блок. При неуспехе исходный блок остаётся действительным, поэтому результат сначала сохраняют во временный указатель. Вместимость и число заполненных элементов — разные величины. Геометрический рост уменьшает число перевыделений. Указатели внутрь старого блока после успешного перемещения становятся недействительными.', 'int *temporary = realloc(values, new_capacity * sizeof *values);\nif (temporary == NULL) { /* values всё ещё принадлежит нам */ }\nelse { values = temporary; capacity = new_capacity; }', 'Реализуй динамический список int с push и destroy. Проверь переполнение размера и неуспешный realloc.'),
('Структуры и инварианты данных','struct объединяет поля одной записи. Передача структуры по значению копирует её поля, но указатель внутри продолжит указывать на прежний объект. Для доступа через указатель используется ->. Структура не гарантирует плотного расположения полей без выравнивающих промежутков. Побайтовая запись struct в файл не является переносимым форматом хранения.', 'struct Book { int id; char title[80]; int available; };\nstruct Book book = {1, "DevCat", 1};\nprintf("%d %s\\n", book.id, book.title);', 'Создай структуру каталога с длиной и ёмкостью. Опиши инварианты и функции, которые имеют право их менять.'),
('enum, typedef и указатели на функции','enum задаёт именованные целочисленные состояния и уменьшает количество магических чисел. typedef создаёт имя типа, но не новый независимый тип. Указатель на функцию позволяет передать поведение, например сравнение для сортировки. Сигнатура указателя должна совпадать с вызываемой функцией; небезопасное приведение не исправляет несовместимость.', 'enum Status { STATUS_OK, STATUS_NOT_FOUND };\ntypedef int (*Predicate)(int);\nint positive(int value) { return value > 0; }', 'Сделай фильтрацию массива через переданный предикат. Добавь enum результата без специальных чисел.'),
('Заголовки, linkage и препроцессор','Препроцессор обрабатывает include и макросы до компиляции. Заголовок публикует объявления, исходный файл содержит определения. Include guard предотвращает повторное включение. static у функции на уровне файла ограничивает внешнюю связность. Макрос подставляет текст и может вычислить аргумент несколько раз, поэтому небольшая функция часто безопаснее макроса.', '#ifndef STATS_H\n#define STATS_H\nint sum_values(const int *values, size_t count);\n#endif', 'Раздели динамический список на заголовок и исходник. Собери два .c-файла и объясни разницу объявления и определения.'),
('Файловые потоки и коды ошибок','fopen возвращает FILE* или NULL. Результат чтения нужно проверять до использования данных, а feof становится полезным после неуспешного чтения, не как предсказатель будущего. fclose может сообщить ошибку финальной записи. errno хранит дополнительную причину только для операций, которые её устанавливают; старое значение нельзя трактовать как новую ошибку.', 'FILE *file = fopen("notes.txt", "r");\nif (!file) { perror("notes.txt"); return 1; }\nchar line[128];\nwhile (fgets(line, sizeof line, file)) fputs(line, stdout);\nfclose(file);', 'Скопируй текстовый файл с проверкой чтения и записи. Убедись, что ошибка не сообщает ложный успех.'),
('Битовые операции и беззнаковые типы','Битовые операции работают с представлением целых: &, |, ^, ~ и сдвиги. Для масок удобны беззнаковые типы из stdint.h. Позиция сдвига должна быть в допустимом диапазоне, а поведение знаковых операций имеет дополнительные ограничения. Маска флагов подходит для независимых признаков, но не заменяет структуру для несвязанных числовых полей.', 'unsigned flags = 0;\nflags |= 1u << 2;\nif (flags & (1u << 2)) puts("Флаг установлен");\nflags &= ~(1u << 2);', 'Сделай набор прав чтения, записи и выполнения. Проверь установку, удаление и независимость флагов.'),
('Неопределённое поведение и диагностика','Знаковое переполнение, выход за массив, двойной free и неверный формат printf могут давать неопределённое поведение. То, что программа однажды напечатала ожидаемое, не делает её корректной. Предупреждения компилятора, AddressSanitizer и UndefinedBehaviorSanitizer помогают обнаружить конкретные ошибки. Их отсутствие не доказывает безопасность всех входов.', 'int value = 5;\nprintf("%d\\n", value);  // Формат соответствует int\nprintf("%zu\\n", sizeof value);  // size_t', 'Исправь три дефекта памяти на маленьких примерах. Сохрани входы как регрессионные тесты и проверь с санитайзерами.'),
('Списки и явное освобождение узлов','Связный список хранит указатель на следующий узел. Вставка после известного узла может быть постоянной по времени, но поиск позиции требует обхода. Каждый узел имеет владельца, а удаление должно сохранять связь оставшихся узлов. Для полного освобождения сначала запоминают next, затем освобождают текущий узел; чтение current->next после free ошибочно.', 'struct Node { int value; struct Node *next; };\nwhile (head) {\n    struct Node *next = head->next;\n    free(head);\n    head = next;\n}', 'Реализуй push_front, поиск и destroy. Проверь пустой список, один узел и удаление головы.'),
('Модульный API и явные контракты','В C нет встроенных классов с private, но непрозрачный тип позволяет скрыть представление структуры в .c-файле. Публичный заголовок задаёт функции создания, операций и уничтожения. Каждый параметр-указатель должен иметь документированное правило NULL, длины и владения. Результат ошибки отделяют от возвращаемых данных.', 'typedef struct Catalog Catalog;\nCatalog *catalog_create(void);\nint catalog_add(Catalog *catalog, const char *title);\nvoid catalog_destroy(Catalog *catalog);', 'Спрячь реализацию каталога за непрозрачным указателем. Напиши таблицу владения аргументами и результатами.'),
('Проект: консольный каталог','Каталог объединяет строки с ограничениями, динамическую память, поиск и файлы. Заранее определи максимальную длину названия и поведение при слишком длинном вводе. При ошибке добавления ранее сохранённые записи должны остаться корректными. Не используй текущий индекс как долговременный идентификатор.', '/* catalog.h, catalog.c, storage.c, main.c */\n/* Команды: add, list, search, remove, save */', 'Собери каталог с устойчивыми id и текстовым форматом экспорта. Проверь утечки, пустые строки и повреждённый файл.'),
('Проект: статистика большого файла','Потоковый анализатор читает данные частями и сохраняет только необходимые счётчики. Граница буфера может разрезать слово или многобайтовый символ, поэтому алгоритм должен сохранять состояние между чтениями. Определи, считаются ли словами последовательности ASCII-букв или полноценный Unicode: второе требует более сложной обработки.', '/* Состояние между блоками: in_word, byte_count, line_count */\n/* Чтение: fread -> обработка -> проверка ferror */', 'Посчитай байты, строки и ASCII-слова без загрузки всего файла. Проверь слово на границе блоков и отсутствие финального перевода строки.'),
('Выпуск C-проекта и переносимость','Зафиксируй стандарт C17, необходимые заголовки, команду сборки и правила формата данных. Не предполагая размер int или порядок байтов, отделяй переносимый код от платформенной части. Предупреждения и тесты должны проходить в новом каталоге сборки. Пользовательская документация описывает действия и ошибки, а не только внутренние структуры.', '/* Внешняя сборка: */\n/* cc -std=c17 -Wall -Wextra -Wpedantic main.c catalog.c -o catalog */', 'Подготовь README, тестовые данные, резервное копирование и проверку двумя компиляторами при наличии. Покажи проект без подсказок.'),
]
SPECIAL['csharp'] = [
('Значимые и ссылочные типы','struct и большинство числовых типов передаются как значения, class — как ссылка на объект. Присваивание ссылки не копирует объект. Строки являются ссылочными, но неизменяемыми. Nullable value type T? хранит значение или отсутствие; nullable reference annotations помогают анализатору, но требуют внимательного использования. ref и out меняют способ передачи и должны быть частью ясного контракта.', 'var first = new List<int> { 1, 2 };\nvar second = first;\nsecond.Add(3);\nConsole.WriteLine(first.Count);', 'Сравни копирование структуры и класса. Сделай независимую копию списка и опиши вложенные ссылки.'),
('Nullable и безопасная обработка отсутствия','Включённый nullable-анализ предупреждает о возможной пустой ссылке. Проверка is not null сужает тип в текущем потоке. ?. выполняет доступ условно, ?? задаёт значение по умолчанию. Оператор ! подавляет предупреждение, но не добавляет проверку во время выполнения. Используй его только при доказанном внешнем инварианте.', 'string? name = Console.ReadLine();\nif (string.IsNullOrWhiteSpace(name)) return;\nConsole.WriteLine(name.Length);', 'Убери необоснованные ! из анкеты. Для каждого отсутствующего поля выбери явную политику.'),
('Классы, свойства и инкапсуляция','Свойство может контролировать чтение и запись, не раскрывая внутреннее поле. Конструктор создаёт корректный объект, private set ограничивает изменение. Не помещай неожиданно тяжёлую операцию в простое чтение свойства. Интерфейс класса должен выражать разрешённые действия, например Reserve, вместо произвольного изменения нескольких связанных полей.', 'class Counter {\n    public int Value { get; private set; }\n    public void Increment() => Value++;\n}', 'Создай товар с проверкой цены и остатка. Реализуй бронирование, сохраняющее инварианты при ошибке.'),
('record и неизменяемые модели','record предоставляет равенство по значениям и удобное создание копии через with. Неизменяемость внешних свойств не гарантирует неизменяемость вложенного List. Разделяй входную DTO-модель, модель предметной области и представление для показа, когда их ограничения различаются. Для небольшого приложения не нужно создавать три слоя без реальной причины.', 'public record Book(int Id, string Title);\n// Внутри метода:\nvar original = new Book(1, "DevCat");\nvar renamed = original with { Title = "Практика" };', 'Сделай неизменяемую запись книги и обновление названия через новую версию. Проверь равенство и вложенные коллекции.'),
('Интерфейсы и композиция','Интерфейс задаёт поведение без привязки к одной реализации. Зависимость от интерфейса хранилища позволяет тестировать сервис без реального файла. Композиция передаёт объекту нужных помощников через конструктор. Не создавай интерфейс для каждого класса автоматически: он нужен на реально изменяемой границе.', 'interface INoteStore {\n    void Save(string text);\n}\nclass ConsoleStore : INoteStore {\n    public void Save(string text) => Console.WriteLine(text);\n}', 'Вынеси сохранение блокнота в интерфейс и реализуй память и файл. Прогони один набор сценариев с обеими реализациями.'),
('Generics и ограничения типов','Обобщённый тип сохраняет информацию об элементах без приведения каждого значения к object. Ограничение where сообщает допустимые операции над T. Коллекция List<T> и словарь Dictionary<TKey,TValue> выражают разные контракты. Не добавляй обобщение, если алгоритм имеет смысл только для одного предметного типа.', 'static T FirstOr<T>(IReadOnlyList<T> values, T fallback) {\n    return values.Count == 0 ? fallback : values[0];\n}', 'Напиши обобщённый контейнер результата поиска и объясни отсутствие boxing для обычного List<int>.'),
('LINQ и отложенное выполнение','Where и Select часто возвращают ленивый IEnumerable. Запрос выполняется при обходе и может увидеть изменения исходной коллекции. ToList материализует результат и фиксирует текущие элементы, но не делает глубокую копию объектов. Читаемая цепочка LINQ удобна, пока в ней нет скрытых побочных эффектов и повторных дорогих проходов.', 'var values = new[] { 1, 2, 3, 4 };\nvar result = values.Where(x => x % 2 == 0).Select(x => x * x).ToList();\nConsole.WriteLine(string.Join(",", result));', 'Сделай отчёт по товарам через LINQ и обычный цикл. Покажи момент выполнения и стоимость повторного обхода.'),
('Делегаты, лямбды и события','Делегат хранит вызываемую операцию с конкретной сигнатурой. Лямбда может захватывать окружение, продлевая жизнь объектов. Событие ограничивает внешнюю подписку и отписку, а издатель решает, когда уведомлять. Неотписанный обработчик долгоживущего объекта может удерживать подписчика. Для вычислений часто достаточно Func и Action.', 'Func<int, int> square = x => x * x;\nConsole.WriteLine(square(5));', 'Добавь уведомление об изменении каталога. Покажи подписку, отписку и тест, который не зависит от реального UI.'),
('IDisposable и using','IDisposable выражает освобождение внешнего ресурса, а using гарантирует Dispose на выходе. Сборщик мусора освобождает память объектов, но не заменяет своевременное закрытие файла. using declaration действует до конца текущей области. Асинхронные ресурсы могут поддерживать IAsyncDisposable и await using.', 'using var stream = new StreamWriter("notes.txt", append: false);\nstream.WriteLine("DevCat");', 'Сохрани данные с гарантированным закрытием и проверкой ошибки записи. Объясни разницу GC и Dispose.'),
('System.Text.Json и валидация DTO','JsonSerializer преобразует объекты в JSON и обратно. Десериализация может вернуть null или заполнить поля значениями по умолчанию, поэтому модель требуется проверить. Настройки имён полей и версий формата фиксируются для совместимости. Не экспортируй секреты вместе с пользовательским прогрессом.', 'var json = System.Text.Json.JsonSerializer.Serialize(new[] { "заметка" });\nvar notes = System.Text.Json.JsonSerializer.Deserialize<string[]>(json);\nConsole.WriteLine(notes?.Length ?? 0);', 'Сделай версионированный экспорт каталога и тест повреждённого поля. Проверь Unicode и неизвестные поля.'),
('Task, async и CancellationToken','async-метод обычно возвращает Task или Task<T>. await ждёт завершения без блокировки потока на время асинхронного ожидания. async void подходит в основном для обработчиков событий, потому что его ошибки трудно наблюдать. CancellationToken передаёт запрос отмены; операция должна его проверять или передавать дальше. Отмена не равна принудительному уничтожению потока.', 'using var source = new CancellationTokenSource();\nawait Task.Delay(20, source.Token);\nConsole.WriteLine("Готово");', 'Сделай отменяемую загрузку локального отчёта с тестовым ожиданием. Проверь завершение и отмену отдельно.'),
('Исключения и диагностический контекст','Лови конкретное исключение на границе операции. throw без аргумента внутри catch сохраняет исходный стек; throw error изменяет его полезный контекст. finally освобождает ресурсы, но using обычно выразительнее. Для ожидаемой ошибки ввода TryParse удобнее исключения. Пользовательское сообщение и технический журнал могут иметь разную подробность.', 'if (!int.TryParse(Console.ReadLine(), out var age)) {\n    Console.WriteLine("Нужно целое число");\n    return;\n}', 'Раздели в программе ошибки формата, отсутствия файла и доступа. Сохрани исходный стек при повторном выбрасывании.'),
('Проект .NET, сборка и тесты','csproj описывает целевую платформу и зависимости. dotnet build компилирует проект, dotnet run запускает, dotnet test выполняет тестовый проект. Версии пакетов и SDK нужно фиксировать для воспроизводимости. Встроенная IDE DevCat собирает локальные исходники без скачивания NuGet; сторонние тестовые фреймворки требуют отдельного подготовленного окружения.', '// Консольное ядро:\nstatic int Cost(int price, int quantity) => checked(price * quantity);', 'Раздели решение на ядро и консольный проект. Подготовь тесты через выбранный фреймворк в своём окружении и опиши зависимости.'),
('Проект: менеджер задач','Менеджер задач объединяет record-модели, сервис, файловое хранение и фильтрацию. Статусы должны быть явными, идентификаторы устойчивыми, переходы допустимыми. Сервис не зависит от Console. Сохранение выполняется после подтверждённого изменения, а ошибки не уничтожают старую версию.', '// Операции: Add, Complete, Reopen, List, Save\n// Поля: Id, Title, Status, CreatedAt', 'Сделай локальный список задач с JSON, поиском и экспортом. Проверь повторное завершение и восстановление резервной копии.'),
('Проект: анализатор расходов','Храни деньги как decimal или целые минимальные единицы. Отдели категорию, дату и сумму от строки ввода. Группировка LINQ создаёт отчёты, но порядок результата задаётся явно. Даты и культура форматирования должны иметь предсказуемые правила обмена.', 'decimal total = 19.90m + 5.10m;\nConsole.WriteLine(total);', 'Реализуй импорт расходов, отчёт по категориям и месяцам, проверки отрицательных сумм и неверных дат.'),
('Выпуск и самостоятельная работа с API','Проверь запуск проекта в новом каталоге, формат данных и восстановление из экспорта. Документация API сообщает nullable-контракт, исключения и условия потокобезопасности. Не копируй пример из другого TargetFramework без проверки доступности. README должен включать версию .NET, команды сборки и известные ограничения.', '// Перед выпуском: build, проверки, экспорт, восстановление\n// Не включай пароли и локальные абсолютные пути', 'Подготовь самостоятельный выпуск менеджера задач и проведи сценарий нового пользователя без подсказок.'),
]
SPECIAL['java'] = [
('JVM, байткод и устройство JDK','JDK включает компилятор javac и инструменты, JVM выполняет байткод. Исходный .java, скомпилированный .class и работающий процесс — разные сущности. Версия байткода должна поддерживаться средой запуска. Пакет задаёт пространство имён и структуру каталогов. Класс с public должен соответствовать имени файла.', 'public class Main {\n    public static void main(String[] args) {\n        System.out.println("DevCat");\n    }\n}', 'Скомпилируй и запусти класс отдельно. Найди версии java и javac и объясни ошибку несовместимой версии.'),
('Примитивы, ссылки и boxing','Примитивные типы хранят значения, переменные объектных типов содержат ссылки. Передача параметра всегда по значению: для объекта копируется ссылка, а не сам объект. Обёртки Integer и другие нужны в обобщённых коллекциях; boxing и unboxing преобразуют представление. Разыменование null и распаковка null вызывают NullPointerException.', 'var first = new java.util.ArrayList<Integer>();\nvar second = first;\nsecond.add(3);\nSystem.out.println(first.size());', 'Покажи различие изменения объекта и переприсваивания параметра. Проверь независимую копию коллекции.'),
('Классы, конструкторы и инкапсуляция','Конструктор создаёт корректный объект, private-поля защищают инварианты. Метод должен выражать действие, а не только открывать произвольную запись во все поля. static относится к классу, не к экземпляру. final запрещает переприсваивание ссылки, но не делает объект неизменяемым. Передавай зависимости явно, вместо скрытых глобальных синглтонов.', 'class Counter {\n    private int value;\n    void increment() { value++; }\n    int value() { return value; }\n}', 'Реализуй счёт с безопасным списанием и тестами отказа. Объясни, что именно защищает private.'),
('record, equals и hashCode','record описывает компактный носитель данных и генерирует равенство по компонентам. Вложенная изменяемая коллекция не становится неизменяемой автоматически. Обычный класс наследует идентичность Object, пока equals не переопределён. Равные по equals объекты обязаны иметь одинаковый hashCode; нарушение ломает поиск в HashMap и HashSet.', 'record Book(int id, String title) {}\n// Внутри main:\nSystem.out.println(new Book(1, "A").equals(new Book(1, "A")));', 'Создай значение ISBN и книгу с идентичностью. Проверь поведение в HashSet и неизменяемость компонентов.'),
('Интерфейсы, наследование и композиция','Интерфейс описывает поведение, реализация выбирает механизм. Наследование выражает отношение подтипа и требует соблюдения контракта базового типа. Композиция удобнее для отношения «использует». Сервису каталога можно передать интерфейс хранилища, а в тесте — реализацию в памяти. Не заставляй модель знать о консольном выводе.', 'interface NoteStore { void save(String text); }\nclass MemoryStore implements NoteStore {\n    public void save(String text) { /* Сохраняем в памяти */ }\n}', 'Выдели интерфейс хранения и две реализации. Проверь один набор операций без реального файла.'),
('Generics, invariance и wildcard','List<Integer> не является подтипом List<Number>, потому что запись произвольного Number нарушила бы тип элементов. extends подходит для источника значений, super — для приёмника по известному правилу PECS. Стирание типов ограничивает информацию во время выполнения. Не используй raw types: они убирают полезные проверки компилятора.', 'static double sum(java.util.List<? extends Number> values) {\n    double total = 0;\n    for (Number value : values) total += value.doubleValue();\n    return total;\n}', 'Напиши типобезопасное копирование между коллекциями и объясни границы wildcard без unchecked-приведений.'),
('Коллекции Java и выбор реализации','ArrayList даёт быстрый доступ по индексу, HashMap связывает ключи с данными, HashSet хранит уникальные значения. LinkedHashMap сохраняет порядок вставки, TreeMap упорядочивает по ключу. Итератор может обнаружить структурное изменение и выбросить ConcurrentModificationException. Это диагностика, а не средство синхронизации потоков.', 'var counts = new java.util.HashMap<String, Integer>();\ncounts.merge("cat", 1, Integer::sum);\ncounts.merge("cat", 1, Integer::sum);\nSystem.out.println(counts.get("cat"));', 'Сделай словарь частот с отсортированным выводом. Сравни порядок HashMap и TreeMap по контракту.'),
('Stream API и побочные эффекты','Stream описывает обработку элементов и обычно выполняется при терминальной операции. Промежуточные filter и map ленивы. Поток одноразовый; повторное использование после терминальной операции ошибочно. Изменяемое внешнее состояние делает цепочку трудной для проверки, особенно при parallel. Сначала выбирай понятное последовательное решение.', 'var values = java.util.List.of(1, 2, 3, 4);\nint total = values.stream().filter(x -> x % 2 == 0).mapToInt(x -> x * x).sum();\nSystem.out.println(total);', 'Сформируй отчёт по категориям через stream и цикл. Объясни терминальную операцию и отсутствие общего накопителя.'),
('Исключения и try-with-resources','Checked-исключения требуют объявления или обработки, unchecked часто сигнализируют о неверном использовании или дефекте. try-with-resources закрывает AutoCloseable даже при исключении. Не перехватывай Exception ради пустого списка без контекста. Причину можно передать конструктору собственного исключения.', 'try (var reader = java.nio.file.Files.newBufferedReader(java.nio.file.Path.of("notes.txt"))) {\n    System.out.println(reader.readLine());\n}', 'Обработай отсутствие файла, ошибку формата и отказ записи разными сообщениями. Проверь закрытие ресурса.'),
('Path, Files и кодировки','Path описывает путь, Files выполняет операции. Задавай UTF-8 явно, если формат обмена это требует. readAllLines удобен для небольших файлов, потоковый reader — для больших. Атомарное перемещение зависит от файловой системы; при отсутствии поддержки нужна понятная стратегия. Не храни абсолютные пути разработчика в переносимом проекте.', 'var path = java.nio.file.Path.of("data", "notes.txt");\njava.nio.file.Files.createDirectories(path.getParent());\njava.nio.file.Files.writeString(path, "DevCat", java.nio.charset.StandardCharsets.UTF_8);', 'Сделай файловое хранилище с временной записью и резервной копией. Проверь кириллицу и новый рабочий каталог.'),
('java.time и корректные даты','Instant представляет момент на временной шкале, LocalDate — календарную дату, ZonedDateTime связывает локальное время с зоной. Не заменяй день фиксированным числом секунд для календарных операций. Формат обмена должен быть явным и независимым от локали интерфейса. Clock можно передать для воспроизводимых тестов времени.', 'var today = java.time.LocalDate.of(2026, 10, 27);\nSystem.out.println(today.plusDays(7));\nSystem.out.println(java.time.Instant.now());', 'Добавь срок возврата книги и тест перехода между месяцами. Отдели текущие часы от вычислительной функции.'),
('Потоки и virtual threads Java 21','Поток выполняет код параллельно, но общий объект требует синхронизации. Virtual threads упрощают большое число блокирующих задач, не ускоряя вычисления на CPU сами по себе. Завершение, исключения и отмена остаются частью контракта. synchronized защищает критическую секцию, а concurrent-коллекции имеют собственные гарантии отдельных операций.', 'Thread worker = Thread.ofVirtual().start(() -> System.out.println("Работа"));\nworker.join();', 'Сделай параллельную обработку независимых файлов и объединение результатов после завершения. Не дели изменяемый список между задачами.'),
('Пакеты, Maven и воспроизводимая сборка','Пакет отделяет имена, система сборки описывает цели, зависимости и тесты. Maven хранит конфигурацию в pom.xml, Gradle использует собственную модель. Для простого офлайн-проекта достаточно javac и стандартной библиотеки; внешние зависимости требуют заранее подготовленного кэша. Версии инструментов и зависимостей должны быть известны.', '// Встроенная IDE собирает .java-файлы проекта через javac\n// Точка входа: public class Main', 'Раздели каталог на несколько классов. Подготовь сборку и тестовый проект в выбранной внешней системе.'),
('Проект: библиотека с командами','Проект объединяет record-модели, интерфейс хранения, коллекции и даты. Устойчивый id отделён от позиции в списке. Валидация команды выполняется до изменения модели. Выдача книги сохраняет инвариант единственного активного займа, а возврат закрывает существующий займ.', '// Модули: Book, Loan, LibraryService, Store, Main\n// Команды: add, search, lend, return', 'Реализуй локальную библиотеку с датами и экспортом. Проверь повторную выдачу, отсутствие книги и повреждённое хранилище.'),
('Проект: анализатор данных и отчёты','Парсер преобразует текст в модель, агрегатор считает результат, форматтер создаёт отчёт. Эти функции можно проверять отдельно. Для числовых сумм выбирай long или BigDecimal по смыслу и границам. Ошибочные записи должны иметь номер строки и понятную причину.', '// parseLine -> Entry\n// summarize -> Map<Category, Total>\n// format -> String', 'Сделай отчёт по расходам с фильтром дат и группировкой. Добавь граничные даты, пустой файл и большие суммы.'),
('Выпуск Java-приложения','Проверь совместимость версии JDK, точку входа, кодировку и рабочий каталог. Документация Java API объясняет исключения, null-контракт и гарантии потокобезопасности. Упаковка JAR не включает автоматически все сторонние зависимости или JVM. README должен описывать реальный способ запуска и требования.', '// Перед выпуском: javac, проверки, чистый каталог, восстановление данных', 'Подготовь JAR в своём окружении и инструкцию запуска. Пройди сценарий нового пользователя без IDE и подсказок.'),
]
SPECIAL['javascript'] = [
('Node.js и браузер: разные среды','ECMAScript задаёт язык, среда предоставляет API. В Node есть fs и process, в браузере — document и DOM. prompt не является универсальной функцией JavaScript. Этот курс запускает локальный Node, поэтому браузерные примеры изучаются отдельно. Версия Node определяет доступные возможности среды и формат модулей.', 'const fs = require("fs");\nconst text = fs.readFileSync(0, "utf8");\nconsole.log(text.trim());', 'Составь карту возможностей Node и браузера. Напиши консольный ввод без prompt и опиши требования запуска.'),
('let, const, привязки и temporal dead zone','let и const имеют блочную область видимости. const запрещает переприсвоить привязку, но не замораживает объект. Обращение до инициализации в temporal dead zone приводит к ошибке. var имеет другие правила области и поднятия, поэтому в новом коде проще начинать с const и использовать let для реального изменения.', 'const values = [1, 2];\nvalues.push(3); // Объект изменился, привязка та же\nlet total = 0;\nfor (const value of values) total += value;', 'Перепиши программу без var и необоснованного let. Покажи разницу изменения массива и переприсваивания.'),
('Преобразования, === и Number','Оператор + может складывать числа или соединять строки. === сравнивает без неявного приведения типов. Number использует IEEE 754, поэтому целые гарантированно точны только в безопасном диапазоне. Number.isNaN проверяет NaN без неявного преобразования. BigInt подходит для больших целых, но его нельзя произвольно смешивать с Number.', 'console.log("2" + 3);\nconsole.log(Number("2") + 3);\nconsole.log(2 === "2");\nconsole.log(Number.isSafeInteger(9007199254740991));', 'Сделай безопасный парсер количества с проверкой пустой строки, NaN и диапазона. Выдели длинный id как строку.'),
('Объекты, ссылки и spread','Объект хранит свойства, массив — упорядоченные элементы. Присваивание копирует ссылку. Spread {...object} и [...array] создаёт поверхностную копию, сохраняя ссылки на вложенные объекты. Object.freeze тоже поверхностен. Деструктуризация упрощает извлечение полей, но отсутствие поля должно иметь явную политику.', 'const first = { profile: { name: "Аня" } };\nconst second = { ...first };\nsecond.profile.name = "Вера";\nconsole.log(first.profile.name);', 'Сделай независимую копию модели заметки с вложенными тегами. Объясни ограничения spread и structuredClone.'),
('Функции, замыкания и this','Функция создаёт область, а замыкание сохраняет доступ к внешнему окружению. Значение this обычной функции зависит от способа вызова; стрелочная функция использует this из окружения. Метод, переданный как callback без привязки, может потерять контекст. Чистая функция с явными аргументами часто проще объекта с неявным состоянием.', 'function makeCounter() {\n    let value = 0;\n    return () => ++value;\n}\nconst next = makeCounter();\nconsole.log(next(), next());', 'Создай два независимых счётчика через замыкание. Добавь пример потерянного this и исправь явной привязкой.'),
('Прототипы и class','Объекты могут делегировать поиск свойств прототипу. class предоставляет привычный синтаксис поверх прототипной модели, но не отменяет её. Поле экземпляра и метод прототипа имеют разные места хранения. Приватные поля # ограничивают доступ. Наследование должно отражать реальный контракт подтипа, а не служить единственным способом повторить код.', 'class Counter {\n    #value = 0;\n    increment() { this.#value++; }\n    get value() { return this.#value; }\n}', 'Реализуй модель товара с закрытым остатком и безопасным резервированием. Сравни с функцией-фабрикой.'),
('Массивы: map, filter, reduce и сортировка','map преобразует, filter выбирает, reduce сворачивает. sort меняет массив на месте и без числового компаратора сравнивает строковые представления. Для чисел используй (a,b)=>a-b. Новые методы копирования доступны не во всех версиях среды; проверяй целевую версию Node. Разреженный массив имеет особенности обхода пустых позиций.', 'const values = [10, 2, 30];\nconst sorted = [...values].sort((a, b) => a - b);\nconsole.log(sorted);', 'Сделай отчёт по товарам без изменения входного массива. Проверь числовую сортировку и пустой reduce с начальным значением.'),
('Map, Set и ключи','Map принимает ключи разных типов и сохраняет порядок вставки. Set хранит уникальные значения по правилам сравнения JavaScript. Обычный объект удобен для известной структуры полей, Map — для динамического словаря. Два разных объекта с одинаковыми полями остаются разными ключами. Для группировки выбирай устойчивый строковый или числовой id.', 'const counts = new Map();\nfor (const word of ["cat", "dog", "cat"]) {\n    counts.set(word, (counts.get(word) ?? 0) + 1);\n}\nconsole.log([...counts]);', 'Реализуй словарь частот и удаление повторов по id, не по ссылке на объект.'),
('CommonJS, ESM и зависимости','CommonJS использует require и module.exports, ESM — import и export. Режим зависит от расширения и package.json. Не смешивай форматы без понимания совместимости. npm устанавливает пакеты, импорт лишь подключает доступный модуль. Lockfile фиксирует дерево зависимостей. Во встроенной IDE простые .js-проекты используют CommonJS без сетевой установки.', '// math.js\nmodule.exports.add = (a, b) => a + b;\n// main.js\nconst { add } = require("./math.js");\nconsole.log(add(2, 3));', 'Раздели консольное приложение на модули. Создай отдельный ESM-пример в подготовленном окружении и объясни режим запуска.'),
('Promise и event loop','Promise представляет будущий результат, а then и await подписываются на завершение. Event loop выполняет очереди задач; асинхронность не делает тяжёлый синхронный цикл параллельным. Microtask с продолжением Promise выполняется раньше следующей обычной задачи после завершения текущего стека. Не блокируй цикл событий длительными вычислениями.', 'console.log("A");\nPromise.resolve().then(() => console.log("B"));\nconsole.log("C"); // Порядок: A, C, B', 'Предскажи порядок нескольких синхронных и асинхронных сообщений. Объясни каждое место через стек и очередь.'),
('async/await и обработка ошибок','async-функция возвращает Promise. await позволяет обрабатывать отклонение через try/catch. Promise.all подходит для независимых операций и отклоняется при первом неуспехе; allSettled собирает все исходы. AbortController передаёт отмену API, которое её поддерживает, но не останавливает произвольный код автоматически.', 'async function main() {\n    const result = await Promise.resolve(42);\n    console.log(result);\n}\nmain().catch(error => { console.error(error.message); process.exitCode = 1; });', 'Сделай асинхронную обработку нескольких локальных файлов с явной политикой частичных ошибок.'),
('fs/promises и безопасное хранение','fs/promises предоставляет асинхронные операции с файлами. Указывай utf8 для текста, проверяй размер и формат. Запись временного файла и rename уменьшают риск частичного сохранения, но поведение замены зависит от платформы. Путь собирают через path, а доступ внешнего имени ограничивают корнем приложения.', 'const fs = require("node:fs/promises");\nasync function save() {\n    await fs.writeFile("notes.json", JSON.stringify([]), "utf8");\n}\nsave().catch(console.error);', 'Сделай хранилище заметок с проверкой схемы, резервной копией и тестами Unicode.'),
('Тесты node:test и assert','Node предоставляет встроенный тестовый модуль и assert/strict. Тесты должны ожидать асинхронные операции, иначе могут завершиться до результата. Передавай зависимости, чтобы не читать реальную консоль в тесте. Для файлов используй временный каталог и гарантированную очистку. Проверяй наблюдаемый контракт, а не случайную внутреннюю структуру.', 'const assert = require("node:assert/strict");\nassert.equal([2, 3].reduce((a, b) => a + b, 0), 5);', 'Создай отдельный тестовый файл с обычными, граничными и ошибочными сценариями. Намеренно внеси дефект и проверь падение.'),
('Проект: локальный менеджер задач','Менеджер объединяет командный ввод, Map, модули, JSON и тесты. У каждой задачи устойчивый id и явный статус. Парсер команды не меняет состояние. Сервис выполняет одну операцию целиком или возвращает ошибку. Хранилище не знает о тексте команд.', '// Модули: parser.js, service.js, storage.js, main.js\n// Команды: add, done, reopen, list', 'Реализуй локальный список задач с поиском и экспортом. Проверь повторную команду и повреждение файла.'),
('Проект: текстовый анализатор','Определи правила слова, регистра и пунктуации. Unicode-регулярные выражения могут отличаться от ASCII-подхода, поэтому контракт должен быть явным. Раздели нормализацию, подсчёт и вывод. Для большого файла сохраняй состояние между частями потока.', 'const words = "Cat dog cat".toLowerCase().split(/\\s+/u);\nconsole.log(words);', 'Сделай частотный анализатор с ограничением памяти и сортировкой по частоте, затем по слову. Проверь пустой текст и кириллицу.'),
('Выпуск Node-приложения','Зафиксируй поддерживаемую версию Node, формат модулей, команды запуска и проверок. Отсутствие браузерного API должно быть понятно пользователю. package-lock сохраняют вместе с package.json при внешних зависимостях. Не включай node_modules, токены и абсолютные пути. Проверь запуск в новом каталоге.', '// README: node main.js, формат данных, версия Node\n// Проверки: node --test в подготовленном проекте', 'Подготовь выпуск CLI и пройди сценарий нового пользователя. Докажи восстановление из экспорта и отсутствие скрытых зависимостей.'),
]
SPECIAL['go'] = [
('Пакеты, модули и устройство программы','Исполняемая программа использует package main и func main. Пакет объединяет файлы каталога, модуль задаёт путь и зависимости через go.mod. Имя с заглавной буквы экспортируется из пакета. Неиспользуемые импорты и локальные переменные вызывают ошибку компиляции. gofmt задаёт единый стиль и снижает количество споров об оформлении.', 'package main\nimport "fmt"\nfunc main() { fmt.Println("DevCat") }', 'Создай проект с несколькими .go-файлами одного пакета. Объясни разницу пакета и модуля.'),
('Массивы, slices и общий backing array','Массив имеет длину как часть типа. Slice — представление участка массива с длиной и ёмкостью. Копирование slice копирует представление, а не элементы. append может использовать прежний массив или выделить новый, поэтому результат нужно присвоить. Для независимой копии используй make и copy или подходящий API стандартной библиотеки.', 'first := []int{1, 2, 3}\nsecond := first[:2]\nsecond[0] = 9\nfmt.Println(first) // [9 2 3]', 'Покажи общий массив двух slices и создай независимую копию. Объясни изменение после append при разной capacity.'),
('map и zero values','map связывает ключ с данными. Чтение отсутствующего ключа возвращает нулевое значение типа, а форма value, ok отличает отсутствие от сохранённого нуля. nil-map допускает чтение, но запись вызывает panic. Порядок обхода map не гарантирован. Для стабильного отчёта собирай и сортируй ключи.', 'counts := make(map[string]int)\ncounts["cat"]++\nvalue, ok := counts["dog"]\nfmt.Println(value, ok)', 'Сделай словарь частот и сортированный вывод. Проверь nil-map, пустую map и сохранённое нулевое значение.'),
('struct, методы и указательные receiver','struct объединяет поля, метод связывает операцию с типом. Value receiver получает копию значения, pointer receiver может менять исходный объект. Выбор влияет на набор методов типа и выполнение интерфейса. Не копируй структуру с mutex после начала использования. Нулевое значение типа полезно делать работоспособным, если это не нарушает инварианты.', 'type Counter struct { value int }\nfunc (c *Counter) Increment() { c.value++ }\nfunc (c Counter) Value() int { return c.value }', 'Реализуй модель остатка товара с pointer receiver. Сравни вызовы на копии и исходном значении.'),
('Интерфейсы и неявное выполнение','Тип выполняет интерфейс, если имеет нужные методы; отдельное объявление implements не требуется. Небольшие интерфейсы удобно определять со стороны потребителя. Значение интерфейса содержит динамический тип и значение, поэтому typed nil может не быть равен nil-интерфейсу. Не возвращай типизированный пустой указатель как успешную ошибку.', 'type Writer interface { Write([]byte) (int, error) }\nfunc Print(w Writer, text string) error {\n    _, err := w.Write([]byte(text))\n    return err\n}', 'Передай хранилище через маленький интерфейс и реализуй память и файл. Разбери пример typed nil.'),
('error, wrapping и errors.Is','Ожидаемый неуспех обычно возвращается отдельным error. Проверяй его сразу, добавляй контекст через fmt.Errorf с %w и сравнивай причины через errors.Is или errors.As. panic не заменяет обычную ошибку пользовательского ввода. Сообщение должно описывать операцию и причину без дублирования бесполезных слов.', 'value, err := strconv.Atoi(text)\nif err != nil {\n    return fmt.Errorf("разобрать возраст: %w", err)\n}\n_ = value', 'Раздели ошибки формата, диапазона и чтения файла. Сохрани возможность проверки исходной причины.'),
('defer и освобождение ресурсов','defer планирует вызов при выходе из функции. Аргументы вычисляются в момент регистрации, а сами вызовы выполняются в обратном порядке. Откладывай Close только после успешного открытия. В длинном цикле defer не срабатывает после каждой итерации: вынеси обработку элемента в отдельную функцию, чтобы не держать много файлов открытыми.', 'file, err := os.Open("notes.txt")\nif err != nil { return err }\ndefer file.Close()\n// Чтение файла', 'Сделай обработку нескольких файлов без накопления открытых дескрипторов. Проверь выход по ошибке.'),
('rune, UTF-8 и текст','string хранит неизменяемую последовательность байтов. len строки возвращает число байтов, а range декодирует UTF-8 в rune — кодовые точки. Индекс range является байтовой позицией. Даже rune не всегда равна видимому символу, поскольку графема может состоять из нескольких кодовых точек. Для ASCII-задачи ограничение алфавита должно быть явным.', 'text := "кот"\nfmt.Println(len(text))\nfor index, symbol := range text {\n    fmt.Println(index, symbol)\n}', 'Сравни длину строки в байтах и rune. Реализуй подсчёт букв по выбранному контракту без порчи UTF-8.'),
('encoding/json и теги полей','encoding/json работает с экспортируемыми полями, а теги задают имена и отдельные правила. После декодирования нужна проверка предметных ограничений. Отсутствующее поле может получить нулевое значение, поэтому для различения отсутствия используют указатель или отдельную модель. Decoder позволяет запретить неизвестные поля, если контракт требует строгости.', 'type Note struct {\n    ID string `json:"id"`\n    Text string `json:"text"`\n}\ndata, err := json.Marshal(Note{ID:"1", Text:"Привет"})\n_ = data; _ = err', 'Сделай версионированный экспорт и строгую загрузку заметок. Проверь неизвестные поля и пустой id.'),
('Goroutines и завершение работы','Goroutine запускает функцию конкурентно, но main не ждёт её автоматически. Для независимых задач используют WaitGroup или другой явный механизм завершения. Не полагайся на sleep как на доказательство, что работа закончилась. Общая изменяемая память требует синхронизации. Конкурентность описывает структуру ожиданий, параллелизм — реальное одновременное выполнение.', 'var group sync.WaitGroup\ngroup.Add(1)\ngo func() { defer group.Done(); fmt.Println("работа") }()\ngroup.Wait()', 'Обработай несколько независимых наборов данных и дождись завершения. Не используй задержку вместо ожидания.'),
('Channels, select и закрытие','Канал передаёт значения и синхронизирует участников. Отправка в закрытый канал вызывает panic, чтение закрытого возвращает оставшиеся значения, затем нулевое и ok=false. Закрывает обычно сторона-отправитель, которая знает, что значений больше не будет. select выбирает готовую операцию, а nil-канал блокирует соответствующую ветвь.', 'values := make(chan int)\ngo func() { defer close(values); values <- 42 }()\nfor value := range values { fmt.Println(value) }', 'Сделай конвейер генерации и обработки значений. Объясни, кто закрывает канал и как завершается каждый участник.'),
('context и кооперативная отмена','Context передаёт срок, отмену и ограниченный служебный контекст через цепочку операций. Не сохраняй его как произвольное поле модели и не используй для обязательных бизнес-параметров. Отмена кооперативна: функция должна проверять Done или вызывать API с поддержкой контекста. cancel требуется вызывать для освобождения связанных ресурсов.', 'ctx, cancel := context.WithTimeout(context.Background(), time.Second)\ndefer cancel()\nselect {\ncase <-ctx.Done(): fmt.Println(ctx.Err())\ncase value := <-values: fmt.Println(value)\n}', 'Добавь отмену конвейера, чтобы ни одна goroutine не оставалась ждать навсегда после остановки потребителя.'),
('testing, table-driven tests и race detector','Файлы *_test.go используют пакет testing. Табличные тесты задают набор входов и ожидаемых результатов. t.Run даёт имя каждому сценарию. go test -race помогает обнаруживать гонки при реально выполненных сценариях. Это отдельный инструмент, не доказательство отсутствия гонок. Бенчмарки измеряют подготовленный участок, а не случайный полный запуск.', 'func TestSum(t *testing.T) {\n    if got := Sum([]int{1, 2}); got != 3 {\n        t.Fatalf("got %d, want 3", got)\n    }\n}', 'Создай табличные тесты пустых, обычных и ошибочных входов. Проверь конкурентную часть с race detector вне приложения.'),
('Проект: потоковый анализатор','Анализатор читает файл построчно или блоками, преобразует строки в события и агрегирует статистику. bufio.Scanner имеет ограничение размера токена, которое нужно учитывать. Ошибка Scanner проверяется после цикла. Потоковый подход не должен незаметно собирать все строки в память.', '// Scanner -> parse -> summarize -> report\n// После обхода: scanner.Err()', 'Создай CLI отчёта по журналу с фильтром, понятными ошибками строк и ограниченным использованием памяти.'),
('Проект: менеджер задач с хранилищем','Отдели модель, сервис, хранение и консоль. Используй устойчивые id, явные ошибки и атомарное сохранение. Интерфейс хранилища позволит запускать тесты без диска. Команды парсятся до изменения модели; при ошибке прежнее состояние остаётся корректным.', '// Файлы: model.go, service.go, storage.go, main.go\n// Операции: Add, Complete, Reopen, List', 'Реализуй локальный менеджер с JSON и резервной копией. Проверь перезапуск и восстановление из экспорта.'),
('Выпуск Go-проекта','go build создаёт исполняемый файл, но переносимость зависит от платформы, архитектуры и cgo-зависимостей. go.mod и go.sum фиксируют зависимости. Документация пакета сообщает контракты, ошибки и конкурентные гарантии. README должен описывать сборку, формат данных и ограничения. Проверь новый каталог и отсутствие скрытых путей.', '// Внешние проверки:\n// gofmt, go vet ./..., go test ./..., go build', 'Подготовь самостоятельный выпуск проекта и инструкцию запуска. Проверь экспорт и восстановление на новом каталоге данных.'),
]
